// Demonstrates atomic counter vs. racy counter using Worker Threads
// Run with: node lock-free-demo.js

const { Worker, isMainThread, parentPort, workerData } = require('worker_threads');

const ITERATIONS = 200_000;
const NUM_WORKERS = 4;

if (isMainThread) {
  // SharedArrayBuffer: slot 0 = atomic counter, slot 1 = racy counter
  const sab = new SharedArrayBuffer(8);
  const shared = new Int32Array(sab);

  const workers = Array.from({ length: NUM_WORKERS }, () =>
    new Promise((resolve, reject) => {
      const w = new Worker(__filename);
      w.once('online', () => w.postMessage(sab));
      w.on('message', resolve);
      w.on('error', reject);
    })
  );

  Promise.all(workers).then(() => {
    const expected = NUM_WORKERS * ITERATIONS;
    console.log(`Expected        : ${expected}`);
    console.log(`Atomic (slot 0) : ${shared[0]}  <- always correct`);
    console.log(`Racy   (slot 1) : ${shared[1]}  <- lost updates!`);
    // Racy will be LESS than expected: read-modify-write is not atomic,
    // so two threads can read the same value, both add 1, and write
    // back the same result — one increment is silently lost.
  });

} else {
  parentPort.once('message', (sab) => {
    const shared = new Int32Array(sab);
    for (let i = 0; i < ITERATIONS; i++) {
      // CORRECT: single atomic fetch-and-add (wait-free)
      Atomics.add(shared, 0, 1);

      // RACY: three separate steps — another thread can interleave between any two
      const old = Atomics.load(shared, 1); // read
      // <-- another thread may read the same 'old' value right here
      Atomics.store(shared, 1, old + 1);   // write: silently overwrites concurrent write
    }
    parentPort.postMessage('done');
  });
}

// C++: publishing data with release/acquire (the data/ready example, done right)
#include <atomic>
#include <cassert>
#include <thread>

int data = 0;                      // plain, non-atomic payload
std::atomic<bool> ready{false};    // the flag is atomic

void producer() {
  data = 42;                                         // 1. write the payload
  ready.store(true, std::memory_order_release);      // 2. publish: earlier writes can't sink below
}

void consumer() {
  while (!ready.load(std::memory_order_acquire)) {}  // 3. later reads can't float above
  assert(data == 42);                                // 4. guaranteed: acquire read the release
}

int main() {
  std::thread a(producer), b(consumer);
  a.join();
  b.join();
}

// With memory_order_relaxed on both, the assert could fail on ARM or POWER.
// seq_cst (the default) also works, at the cost of a full fence on x86 stores.
// Java: a volatile write + volatile read gives the same guarantee.
// Rust: AtomicBool::store(true, Ordering::Release) / load(Ordering::Acquire).

// CAS loop as the lock-free building block
// Atomics.compareExchange is JavaScript's CAS: it returns the value it found.

const counter = new Int32Array(new SharedArrayBuffer(4));

/**
 * Lock-free add by an arbitrary delta using a CAS retry loop.
 * Lock-free (not wait-free): a thread may retry while others succeed.
 * Atomics.add does the same thing in a single wait-free instruction on x86.
 */
function lockFreeAdd(arr, index, delta) {
  let expected = Atomics.load(arr, index);               // 1. read current value
  while (true) {
    const desired = expected + delta;                     // 2. compute locally
    const actual = Atomics.compareExchange(arr, index, expected, desired); // 3. CAS
    if (actual === expected) return desired;              // swap succeeded
    expected = actual;  // 4. someone else won — retry with the value CAS just returned
  }
}
console.log(lockFreeAdd(counter, 0, 5)); // 5

// ── ABA defence: a version stamp updated in the SAME atomic operation ──
// Pack a 32-bit value and a 32-bit version into one 64-bit word, so a single
// BigInt64 CAS checks both at once (the same idea as tagged pointers or
// x86's 128-bit CMPXCHG16B for pointer + counter).
const cell = new BigInt64Array(new SharedArrayBuffer(8));
const pack = (value, version) => (BigInt(version) << 32n) | BigInt(value >>> 0);
const unpack = (word) => ({ value: Number(word & 0xffffffffn) | 0, version: Number(word >> 32n) });

Atomics.store(cell, 0, pack(100, 0));

function casVersioned(expectedValue, expectedVersion, newValue) {
  const expected = pack(expectedValue, expectedVersion);
  const desired = pack(newValue, expectedVersion + 1);    // every write bumps the version
  const found = Atomics.compareExchange(cell, 0, expected, desired);
  return found === expected ? { success: true, ...unpack(desired) } : { success: false, ...unpack(found) };
}

// Thread T1 reads (value 100, version 0) … and is preempted.
// Meanwhile T2 changes 100 → 200 → 100 (A → B → A):
console.log(casVersioned(100, 0, 200)); // { success: true, value: 200, version: 1 }
console.log(casVersioned(200, 1, 100)); // { success: true, value: 100, version: 2 }
// T1 resumes. A plain value CAS (100 → 300) would succeed — the ABA problem.
// The versioned CAS sees version 2, not 0, and correctly fails:
console.log(casVersioned(100, 0, 300)); // { success: false, value: 100, version: 2 }
